number.script:
          function onInit()
            local sDBnode = window.getDatabaseNode();           
            nLevel = DB.getValue(sDBnode,"level",1);

            -- use DB value as source of truth
            nLevel = CompanionData.validateLevel(nLevel);
            setValue(nLevel);
            
            -- updateCosts();
          end
          function onValueChanged()
            local nLevel = CompanionData.validateLevel(getValue());
            DB.setValue(window.getDatabaseNode(),"level","number",nLevel);

            updateCosts();
          end
          function updateCosts()
            local sDBnode = window.getDatabaseNode();
            local nLevel = getValue() or 1;

            -- in case the level or HP were not set yet
            DB.setValue(sDBnode,"level","number",nLevel);
            local nHP = CompanionData.getLevelHP(nLevel);

            -- set the window so it can update the DB node
            window.current_maxHP.setValue(nHP);

            local nCost = CompanionData.getLevelCost(nLevel);
            window.cost_current.setValue(nCost);

            local nUpgradeCost = CompanionData.getLevelCost(nLevel + 1);
            window.cost_upgrade.setValue(nUpgradeCost);
          end

buttoncontrol.script:
function onButtonPress()
  local nLevel = window.current_level.getValue();
  nLevel = CompanionData.validateLevel(nLevel + 1);
  window.current_level.setValue(nLevel);
end

function onButtonPress()
  local nLevel = window.current_level.getValue();
  nLevel = CompanionData.validateLevel(nLevel - 1);
  window.current_level.setValue(nLevel);
end

number.script:
          function onValueChanged()
            local sDBnode = window.getDatabaseNode();
            local nMaxHP = getValue() or 0;

            local nodeHP = DB.getChild(sDBnode,"hp");
            DB.setValue(nodeHP, "total",   "number", nMaxHP);
            DB.setValue(nodeHP, "current", "number", nMaxHP);
            Debug.console("Set Max HP to " .. nMaxHP);
          end

function onValueChanged()
  local sDBnode = window.getDatabaseNode();
  local nCurrentCost = getValue() or 0;
  DB.setValue(sDBnode,"currentcost","number",nCurrentCost);
  Debug.console("Set Current Cost to " .. nCurrentCost);
end

function onValueChanged()
  local sDBnode = window.getDatabaseNode();
  local nCurrentCost = window.cost_current.getValue() or 0;
  local nUpgradeCost = getValue() or 0;
  local nTrainingCost = nUpgradeCost - nCurrentCost;
  DB.setValue(sDBnode,"traincost","number",nTrainingCost);
  Debug.console("Set Training Cost to " .. nTrainingCost);
end

button_stringcycler.script:
				function onValueChanged()
				  local sStat = getValue();
				  Debug.console("Primary Stat set to: " .. sStat);

          -- get the primary stat modifier for their level and set the score of that ability to 10 + modifier.
          local nLevel = window.current_level.getValue() or 0;
          local nModifier = CompanionData.getLevelFirstAbility(nLevel);
         
           -- set ability score
          local sDBnode = window.getDatabaseNode();
          local nodeAbilityScore = DB.getChild(sDBnode,"abilities." .. sStat .. ".score");
          local nAbilityScore = 10 + nModifier;
          DB.setValue(nodeAbilityScore,"number",nAbilityScore);
          Debug.console("Set Primary Stat Score to: " .. nAbilityScore);

          -- set ability score bonus
          local nodeAbilityBonus = DB.getChild(sDBnode,"abilities." .. sStat .. ".bonus");
          local statBonus = CompanionData.getStatBonus(nAbilityScore);
          DB.setValue(nodeAbilityBonus,"number",statBonus);
				end

				function onValueChanged()
				  local sStat = getValue();
				  Debug.console("Secondary Stat set to: " .. sStat);

          -- get the secondary stat modifier for their level and set the score of that ability to 10 + modifier.
          local nLevel = window.current_level.getValue() or 0;
          local nModifier = CompanionData.getLevelSecondAbility(nLevel);
         
           -- set ability score
          local sDBnode = window.getDatabaseNode();
          local nodeAbilityScore = DB.getChild(sDBnode,"abilities." .. sStat .. ".score");
          local nAbilityScore = 10 + nModifier;
          DB.setValue(nodeAbilityScore,"number",nAbilityScore);
          Debug.console("Set Primary Stat Score to: " .. nAbilityScore);

          -- set ability score bonus
          local nodeAbilityBonus = DB.getChild(sDBnode,"abilities." .. sStat .. ".bonus");
          local statBonus = CompanionData.getStatBonus(nAbilityScore);
          DB.setValue(nodeAbilityBonus,"number",statBonus);
				end

button_details.script:
					function onButtonPress()
            local sDBnode = window.getDatabaseNode();
            Debug.console("DB Node: " .. sDBnode.getPath());

            local sRuleset = Interface.getRuleset();
            Debug.console("Using ruleset: " .. sRuleset, true);

            Interface.openWindow("companionSetDefaults", sDBnode);
					end

number.script:
          function onInit()
            local nLevel = getValue();
            local sDBnode = window.getDatabaseNode();
            nLevel = DB.getValue(sDBnode,"level",1);
            setValue(nLevel);
            updateCosts();
          end
          function onValueChanged()
            updateCosts();
          end
          function updateCosts()
            local sDBnode = window.getDatabaseNode();
            local nLevel = getValue() or 0;

            -- in case the level or HP were not set yet
            DB.setValue(sDBnode,"level","number",nLevel);
            local nHP = CompanionData.getLevelHP(nLevel);

            -- set the window so it can update the DB node
            window.current_maxHP.setValue(nHP);

            local nCost = CompanionData.getLevelCost(nLevel);
            window.cost_current.setValue(nCost);

            local nUpgradeCost = CompanionData.getLevelCost(nLevel + 1);
            window.cost_upgrade.setValue(nUpgradeCost);
          end

          function onValueChanged()
            local sDBnode = window.getDatabaseNode();
            local nMaxHP = getValue() or 0;

            local nodeHP = DB.getChild(sDBnode,"hp");
            DB.setValue(nodeHP, "total",   "number", nMaxHP);
            DB.setValue(nodeHP, "current", "number", nMaxHP);
            Debug.console("Set Max HP to " .. nMaxHP);
          end

function onValueChanged()
  local sDBnode = window.getDatabaseNode();
  local nCurrentCost = getValue() or 0;
  DB.setValue(sDBnode,"currentcost","number",nCurrentCost);
  Debug.console("Set Current Cost to " .. nCurrentCost);
end

function onValueChanged()
  local sDBnode = window.getDatabaseNode();
  local nCurrentCost = window.cost_current.getValue() or 0;
  local nUpgradeCost = getValue() or 0;
  local nTrainingCost = nUpgradeCost - nCurrentCost;
  DB.setValue(sDBnode,"traincost","number",nTrainingCost);
  Debug.console("Set Training Cost to " .. nTrainingCost);
end

